<script setup lang="ts">import { computed,ref } from 'vue';import { Search,Reading } from '@element-plus/icons-vue';import PageHeader from '@/components/PageHeader.vue';import { knowledgeArticles } from '@/data/demo';const keyword=ref('');const category=ref('全部');const list=computed(()=>knowledgeArticles.filter(x=>(category.value==='全部'||x.category===category.value)&&(x.title+x.summary).includes(keyword.value)));</script>
<template><div class="knowledge-hero"><div class="container"><span class="section-label">ENTERPRISE KNOWLEDGE BASE</span><h1 class="serif">跨境知识，有版本、有审核、有出处。</h1><p>聚合商品知识、政策法规与通关流程。只有审核发布且在有效期内的内容进入检索与 AI 问答。</p><el-input v-model="keyword" size="large" :prefix-icon="Search" placeholder="搜索政策名称、通关环节、商品知识……" clearable/></div></div><div class="page-shell"><div class="container knowledge-layout"><aside class="paper-card"><b>知识分类</b><button v-for="c in ['全部','政策法规','通关流程','商品知识']" :key="c" :class="{active:category===c}" @click="category=c">{{c}}<span>{{c==='全部'?knowledgeArticles.length:knowledgeArticles.filter(x=>x.category===c).length}}</span></button><div class="ai-entry"><el-icon><Reading/></el-icon><b>找不到答案？</b><p>让 AI 在已发布知识中检索并标注引用。</p><el-button type="primary" size="small" @click="$router.push('/ai-service')">咨询 AI</el-button></div></aside><main><PageHeader eyebrow="PUBLISHED KNOWLEDGE" :title="category==='全部'?'全部已发布知识':category" :description="`共 ${list.length} 条有效内容，按最近更新排序`"/><div class="article-list"><RouterLink v-for="article in list" :key="article.id" :to="`/knowledge/${article.id}`"><div class="article-mark">{{article.category.slice(0,1)}}</div><div><div class="meta"><el-tag size="small" effect="plain">{{article.category}}</el-tag><span>{{article.authority}}</span><span>版本 {{article.version}}</span></div><h2 class="serif">{{article.title}}</h2><p>{{article.summary}}</p><small>更新于 {{article.date}} · 已审核发布</small></div></RouterLink></div></main></div></div></template>
<style scoped>.knowledge-hero{padding:70px 0;background:linear-gradient(120deg,#083d39,#0c5b54);color:#fff}.knowledge-hero h1{margin:12px 0;font-size:43px}.knowledge-hero p{color:#b7cbc5}.knowledge-hero .el-input{width:min(680px,100%);margin-top:22px}.knowledge-layout{display:grid;grid-template-columns:230px 1fr;gap:34px}.knowledge-layout aside{height:max-content;padding:20px;position:sticky;top:120px}.knowledge-layout aside>b{display:block;margin:5px 8px 14px}.knowledge-layout aside>button{width:100%;display:flex;justify-content:space-between;padding:10px 12px;border:0;border-radius:7px;background:transparent;color:var(--muted);cursor:pointer}.knowledge-layout aside>button.active{background:var(--jade-soft);color:var(--jade);font-weight:700}.knowledge-layout aside>button span{font-size:11px}.ai-entry{margin-top:22px;padding:18px;background:#f1ecdf;border-top:3px solid var(--gold)}.ai-entry .el-icon{color:var(--cinnabar);font-size:24px}.ai-entry b{display:block;margin-top:8px}.ai-entry p{color:var(--muted);font-size:12px;line-height:1.7}.article-list{display:grid;gap:12px}.article-list>a{display:grid;grid-template-columns:55px 1fr;gap:18px;padding:22px;background:rgba(255,255,255,.8);border:1px solid var(--line);transition:.2s}.article-list>a:hover{border-color:var(--jade);transform:translateX(4px)}.article-mark{width:52px;height:58px;display:grid;place-items:center;background:var(--jade);color:#fff;font:700 24px 'Noto Serif SC',serif}.meta{display:flex;align-items:center;gap:13px;color:var(--muted);font-size:11px}.article-list h2{margin:10px 0 7px;font-size:19px}.article-list p{margin:0 0 10px;color:var(--muted);line-height:1.7}.article-list small{color:#87938f}@media(max-width:750px){.knowledge-layout{grid-template-columns:1fr}.knowledge-layout aside{position:static}.knowledge-hero h1{font-size:34px}}</style>
